+	config.whatChanged = changed
+
+	if err := init(config); err != nil {
+		return err
+	}
+
+	var cacheBusterOr func(string) bool
+	if len(cacheBusters) > 0 {
+		cacheBusterOr = func(s string) bool {
+			for _, cb := range cacheBusters {
+				if cb(s) {
